import px2vw from "./px2vw";
/**
 * Get the scroll position.
 *
 * @param {any}
 * @param {string} [unit='px']
 * @returns {Point}
 */
const getScrollPosition = (el = null, unit = "px") => {
    el = el ? el : window;
    const scrollPosition = {
        x: el.pageXOffset !== undefined
            ? el.pageXOffset
            : el.scrollLeft,
        y: el.pageYOffset !== undefined
            ? el.pageYOffset
            : el.scrollTop,
    };
    if (unit === "vw") {
        scrollPosition.x = px2vw(scrollPosition.x);
        scrollPosition.y = px2vw(scrollPosition.y);
    }
    return scrollPosition;
};
/**
 * Get the scroll position as vw unit.
 *
 * @param {any}
 * @returns {Point}
 */
const getScrollPositionAsVw = (el = null) => getScrollPosition(el, "vw");
export { getScrollPosition, getScrollPositionAsVw };
